  const launch=mine.filter(p=>p.launch!=null&&p.launch>=B.d&&p.review!=null).sort((a,b)=>a.launch-b.launch).map(p=>({n:p.name,c:p.cat,d:p.launch,rv:p.review}));
  const port=mine.filter(p=>p.active).map(p=>{const hw=HW.includes(p.cat);return {n:p.name,c:p.cat,sh:Math.round(p.share*1000)/1000,hw,u:hw?Math.max(0,Math.round((p.total||0)-(B.pt[p.id]||0))):Math.round(p.units||0),rv:p.review!=null?p.review:null};}).sort((a,b)=>b.sh-a.sh).slice(0,8);
